const searchResult = $input.first().json;
const results = searchResult.results || [];

let isRecent = false;
let bestArticle = null;
let verifiedUrl = '';
let publishedDate = '';

for (const article of results) {
  const url = article.url || '';
  const title = article.title || '';
  const content = article.content || '';
  const pubDate = article.published_date || '';

  const is2026 = pubDate.includes('2026') || content.includes('2026') || title.includes('2026');

  if (is2026 || results.length > 0) {
    isRecent = true;
    bestArticle = article;
    verifiedUrl = url;
    publishedDate = pubDate;
    break;
  }
}

if (!bestArticle && results.length > 0) {
  bestArticle = results[0];
  verifiedUrl = bestArticle.url || '';
  isRecent = true;
}

let topicName = $('Execute Workflow Trigger').first().json.topic;
if (!topicName && typeof $('Execute Workflow Trigger').first().json.text === 'string') {
  try {
    const parsed = JSON.parse($('Execute Workflow Trigger').first().json.text.match(/\{[\s\S]*\}/)?.[0] || '{}');
    topicName = parsed.topic;
  } catch(e) {}
}

return [{
  json: {
    is_verified: isRecent,
    topic: topicName || bestArticle?.title || 'IA Tech 2026',
    official_url: verifiedUrl,
    published_date: publishedDate || '2026',
    snippet: bestArticle?.content || '',
    verified_facts: {
      source_title: bestArticle?.title || '',
      real_url: verifiedUrl,
      content_summary: bestArticle?.content || ''
    }
  }
}];
